MonthlyBreakdownOfYearlyDiscounts = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=MonthlyBreakdownOfYearlyDiscounts]");
        var years = await MonthlyBreakdownOfYearlyDiscounts.getYears(app);
        var data = await MonthlyBreakdownOfYearlyDiscounts.getData(years, app);
        MonthlyBreakdownOfYearlyDiscounts.initChart(container, data, app.Config.B2B.Currencies, years);
    },

    getYears: async function (app) {
        var minOfferData = (await api.get(`B2B/Offer/FromSystem(SystemId='${app.Config.B2B.SourceSystem}')?$select=DueDate&$orderby=DueDate asc&$top=1`)).value;
        var maxOfferData = (await api.get(`B2B/Offer/FromSystem(SystemId='${app.Config.B2B.SourceSystem}')?$select=DueDate&$orderby=DueDate desc&$top=1`)).value;
        if (minOfferData.length > 0) { minOfferData = new Date(minOfferData[0].DueDate); }
        if (maxOfferData.length > 0) { maxOfferData = new Date(maxOfferData[0].DueDate); }
        var years = [];

        if(minOfferData.length > 0 &&  maxOfferData.length > 0) {
            var numberOfYears = Math.max(Math.abs((new Date(maxOfferData - minOfferData)).getUTCFullYear() - 1970), 1);
            for (let i = 0; i < numberOfYears; i++) { years.push(minOfferData.getFullYear() + i); }
        }

        return years;
    },

    transformData: function(chartData, month, year, app) {
        if (chartData.length > 0) {
            for (let c in app.Config.B2B.Currencies) {
                var matchingCurrency = chartData.filter(r => r.CurrencyId === app.Config.B2B.Currencies[c]);
                if (matchingCurrency.length > 0) {
                    return matchingCurrency.map(r => { r.CalendarMonth = year + "-" + month; return r; });
                } else {
                    return { CalendarMonth: year + "-" + month, Cost: 0, Total: 0, CurrencyId: app.Config.B2B.Currencies[c] };
                }
            }
        } else {
            for (let c in app.Config.B2B.Currencies) {
                return { CalendarMonth: year + "-" + month, Cost: 0, Total: 0, CurrencyId: app.Config.B2B.Currencies[c] };
            }
        }
    },

    getData: async function (years, app) {
        var data = [];
        return (await Promise.all(years.map(async y => {
            for (let i = 0; i < 12; i++) {
                var offerData = await  api.get(`B2B/Offer/FromSystem(SystemId='${app.Config.B2B.SourceSystem}')?$apply=filter(month(DueDate) eq ${i+1} and year(DueDate) eq ${y} and (FunderState eq 'FundingAccepted' or CreditorState eq 'FundingAccepted' or FunderState eq 'Paid'))/groupby((CurrencyId), aggregate(Id with countdistinct as Total, Cost with sum as Cost))`);
                data.push(MonthlyBreakdownOfYearlyDiscounts.transformData(offerData, i+1, y, app));
            }
            return (await Promise.all(data)).flat();
        }))).flat();
    },

    initChart: function (container, data, currencies, years) {
        var categories = data.map(i => i.CalendarMonth).filter((value, index, self) => self.indexOf(value) === index);
        console.log({ component: "MonthlyBreakdownOfYearlyDiscounts", data: data });
        var args = {
            width: $(container).width(),
            height: "500px",
            showLegend: true,
            valueTemplate: "#: kendo.toString(value, type.aggregateMoneyFormat)#",
            tooltipTemplate: "#= series.name #: #= kendo.toString(value, type.aggregateMoneyFormat) #",
            series: years.map(y => currencies.map(cur => ({
                name: "[resource_displayname[Cost]] (" + cur + ")",
				style: "smooth",
				line: {
					style: "smooth"
				},
                data: categories.map(c => data.filter(r => r.CalendarMonth.split("-")[0] === y.toString() && r.CalendarMonth === c && r.CurrencyId === cur).map(i => i.Cost))
            }))).flat(),
            categories: categories,
            max: data.map(i => i.Cost).sort((a, b) => b - a)[0],
            type: "line"
        };
        (new Chart($("[name=chart]", container), args)).init();
    }
}
